import{z as o,x as A,o as t,c as m,q as d,j as n,D as s,d as e,s as l,S as E,b as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"md 软 RAID","description":"","frontmatter":{"title":"md 软 RAID","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/md-raid.md","filePath":"cs/md-raid.md","lastUpdated":1791063341000}'),D={name:"cs/md-raid.md"};function p(B,a,c,u,h,R){const i=A("Mermaid");return t(),m("div",null,[a[2]||(a[2]=d('<h1 id="md-软-raid" tabindex="-1">md 软 RAID <a class="header-anchor" href="#md-软-raid" aria-label="Permalink to &quot;md 软 RAID&quot;">​</a></h1><div class="epigraph"><p>md 在内核里把多块盘组成线性、0/1/4/5/6/10 等阵列：超级块记下角色，bitmap 加速恢复，/dev/md* 仍是一块块设备。</p><footer>—— 据 Linux MD RAID 文档；Patterson, Gibson, Katz, A Case for Redundant Arrays of Inexpensive Disks, SIGMOD 1988</footer></div><p><a href="/cs/device-mapper-lvm">上一课</a>用表拼接空间。冗余可以走 dm-raid，也可以走更老的 <strong>md</strong>。缺口是软 RAID 作为块设备：条带、镜像、奇偶，以及重建——写洞留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单盘故障丢数据。RAID1 写两份；RAID0 只条带不冗余；RAID5/6 用奇偶。md：每盘尾部或前部超级块描述成员，装配出 <code>/dev/md0</code>。缺口：reshape、热备、坏块列表、写意图位图（避免整盘 resync）。与 SCSI/NVMe 无关：成员是任意块设备。本课不把硬件 RAID 卡的固件写进来。</p><p><span class="marginnote">数字实例：chunk 取 512 KiB 时，一个 1 MiB 的连续写在 RAID0 上正好劈成两半，两块盘各写 512 KiB 并行；chunk 太小会把大写切成太多请求，太大则一个小的随机写也要占满一整条带，两头都伤带宽。</span></p><p><span class="marginnote">chunk 大小影响 FS 块组对齐。外部元数据与 IMSM 等格式存在，教学以原生 md 超级块为准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写 RAID1：克隆 bio 到两成员，都完成后才完成上层。写 RAID0：按 chunk 选盘。读可从较空闲镜像腿。故障：标记坏腿，热备接替，恢复线程拷数据。对照 LVM：md 的对象是冗余几何，不是灵活扩容（虽可线性）。对照 <a href="/cs/fs-checksum-scrub">FS 校验</a>：md 不默认端到端校验用户数据（除非额外 integrity target）。</p><p><span class="marginnote">术语翻译：写意图位图是「改动记录表」——阵列给每个 chunk 记一个脏位。掉电重启后 resync 只重算标脏的块，而不是整盘从头对抄，恢复窗口从小时级缩到分钟级；它加速恢复，但不替代奇偶本身的正确性。</span></p>',10)),(t(),n(E,null,{default:s(()=>[l(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22FS%20%E6%88%96%20dm%22%5D%20--%3E%20MD%5B%22md%20%E9%98%B5%E5%88%97%22%5D%0A%20%20MD%20--%3E%20D0%5B%22%E6%88%90%E5%91%98%E7%9B%98%200%22%5D%0A%20%20MD%20--%3E%20D1%5B%22%E6%88%90%E5%91%98%E7%9B%98%201%22%5D%0A%20%20MD%20--%3E%20P%5B%22%E5%8F%AF%E9%80%89%E5%A5%87%E5%81%B6%E7%9B%98%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("软 RAID 用 CPU 与总线换独立 RAID 卡。它把「一块逻辑盘」的假象维持给 "),r("a",{href:"/cs/vfs"},"VFS"),e(" 底下的 FS。性能与故障模式取决于级别——下一课专门讲级别与写洞。不要把 md 写成分布式一致性：成员假定在同一台机器的块层。")],-1)),a[5]||(a[5]=r("p",null,"同一次逻辑写，落在不同级别上变成的物理动作完全不同：",-1)),(t(),n(E,null,{default:s(()=>[l(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%80%E6%AC%A1%E9%80%BB%E8%BE%91%E5%86%99%22%5D%20--%3E%20R1%5B%22RAID1%EF%BC%9A%E5%85%8B%E9%9A%86%E5%86%99%E4%B8%A4%E4%BB%BD%22%5D%0A%20%20W%20--%3E%20R0%5B%22RAID0%EF%BC%9A%E6%8C%89%20chunk%20%E8%90%BD%E5%8D%95%E7%9B%98%22%5D%0A%20%20W%20--%3E%20R5%5B%22RAID5%EF%BC%9A%E6%95%B0%E6%8D%AE%E7%9B%98%E5%8A%A0%E5%A5%87%E5%81%B6%E7%9B%98%22%5D%0A%20%20R1%20--%3E%20BOTH%5B%22%E4%B8%A4%E4%BB%BD%E9%83%BD%E5%AE%8C%E6%88%90%E6%89%8D%E5%90%91%E4%B8%8A%E6%8A%A5%E5%AE%8C%E6%88%90%22%5D%0A%20%20R5%20--%3E%20RMW%5B%22%E5%A5%87%E5%81%B6%E9%87%8D%E7%AE%97%EF%BC%9A%E8%AF%BB%E6%94%B9%E5%86%99%E6%88%96%E9%87%8D%E6%9E%84%E5%86%99%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<p><span class="marginnote">直觉类比：RAID0 像把一本书的页拆给两台复印机各印一半——快一倍，但任何一台卡纸书就缺页；RAID1 是完整印两本；RAID5 是另记一本「异或账」，丢任何一页都能用其余页把账推回来。</span></p><p>与调度器：每个成员有自己的队列；条带把一次逻辑写打成多次物理写。</p><p>实现上：reshape 改条带宽度时要搬数据，期间性能与失败模型都变。写意图位图不能替代奇偶正确性，只能缩短「整盘重算」的窗口。 读法上只引用<a href="/cs/device-mapper-lvm">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>md 软 RAID</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cluster MD。不保证 USB 盘做 RAID 的可靠性。下一课把 Patterson 的级别与 RAID5 写洞钉成明确缺口。</p><p>版本字段会变，课序钉的是机制对象「md 软 RAID」，不是某一主线内核的结构体名。 后课默认：md 提供冗余块设备。条带/镜像/奇偶的更新原子性裂缝，下一课写洞。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>md 用超级块装配软 RAID，对上仍是块设备。</li><li>位图缩短恢复；校验数据仍宜在 FS 层。</li><li>RAID 级别与写洞是下一课。</li><li>出处：Linux MD；Patterson et al., SIGMOD 1988；<em>OSTEP</em>。</li></ul>',10))])}const S=o(D,[["render",p]]);export{f as __pageData,S as default};
